package com.diberlog.jarvis.mobile;

import android.content.Context;
import org.json.*;

/** Unsent text and extracted documents stay in the encrypted local snapshot, outside sync records. */
final class ChatDrafts {
    static JSONObject all(Context c)throws Exception{JSONObject snapshot=SyncJournal.snapshot(c);if(!snapshot.has("chat_drafts"))return new JSONObject();return snapshot.getJSONObject("chat_drafts");}
    static JSONObject read(Context c,String id)throws Exception{JSONObject all=all(c);return all.has(id)?new JSONObject(all.getJSONObject(id).toString()):new JSONObject().put("text","").put("attachments",new JSONArray());}
    static void write(Context c,String id,String text,JSONArray attachments)throws Exception{if(id.isEmpty())return;if(text.length()>220000||attachments.length()>3)throw new Exception("Черновик слишком большой");int length=0;for(int n=0;n<attachments.length();n++){JSONObject doc=attachments.getJSONObject(n);length+=doc.getString("text").length();if(doc.getString("name").length()>160)throw new Exception("Слишком длинное имя документа");}if(length>200000)throw new Exception("Документы вместе: до 200 000 символов");synchronized(SyncJournal.class){JSONObject all=all(c);if(text.isEmpty()&&attachments.length()==0){if(!all.has(id))return;all.remove(id);}else{JSONObject value=new JSONObject().put("text",text).put("attachments",new JSONArray(attachments.toString()));if(MobileStore.same(all.opt(id),value))return;all.put(id,value);}if(all.toString().length()>4*1024*1024)throw new Exception("Слишком много несохранённых черновиков");SyncJournal.save(c,"chat_drafts",all);}}
    static void text(Context c,String id,String text)throws Exception{synchronized(SyncJournal.class){JSONObject saved=read(c,id);write(c,id,text,saved.getJSONArray("attachments"));}}
    static void append(Context c,String id,String name,String text)throws Exception{synchronized(SyncJournal.class){JSONObject saved=read(c,id);JSONArray docs=saved.getJSONArray("attachments");docs.put(new JSONObject().put("id",MobileStore.id()).put("name",name).put("text",text));write(c,id,saved.getString("text"),docs);}}
    static void remove(Context c,String id,String text,JSONObject selected)throws Exception{synchronized(SyncJournal.class){JSONArray all=read(c,id).getJSONArray("attachments"),keep=new JSONArray();boolean removed=false;for(int n=0;n<all.length();n++){JSONObject doc=all.getJSONObject(n);boolean same=selected.has("id")?selected.getString("id").equals(doc.optString("id")):MobileStore.same(selected,doc);if(!removed&&same){removed=true;continue;}keep.put(doc);}write(c,id,text,keep);}}
    static String prompt(String text,JSONArray attachments)throws Exception{StringBuilder query=new StringBuilder(text.trim());if(query.length()==0&&attachments.length()>0)query.append("Прочитай приложенные документы и кратко опиши их содержание.");for(int n=0;n<attachments.length();n++){JSONObject doc=attachments.getJSONObject(n);query.append("\n\n--- Документ: ").append(doc.getString("name")).append(" ---\n").append(doc.getString("text")).append("\n--- Конец документа ---");}if(query.length()>220000)throw new Exception("Запрос вместе с документами слишком большой. Уберите документ или сократите текст.");return query.toString();}
}
